def solve_maze(inp,pattern,marker,starts,corridor,key_cells):
    o=[r[:] for r in inp];bg=inp[0][0]
    for r,c in key_cells:o[r][c]=bg
    n=len(inp);m=len(inp[0]);seen=set()
    def horiz(row,col,initial=False):
        if not (0<=row<n and 0<=col<m) or (inp[row][col]!=corridor and not initial):return None
        c=col;idx=0;o[row][c]=pattern[0]
        while c+1<m and inp[row][c+1]==corridor:
            c+=1;idx+=1;o[row][c]=pattern[idx%len(pattern)]
        if c+1<m:o[row][c+1]=marker
        return c
    def vert_all(col):
        if col in seen or not(0<=col<m):return
        seen.add(col);runs=[];r=0
        while r<n:
            if inp[r][col]!=corridor:r+=1;continue
            top=r
            while r+1<n and inp[r+1][col]==corridor:r+=1
            runs.append((top,r));r+=1
        for top,bottom in runs:
            for i,rr in enumerate(range(bottom,top-1,-1)):o[rr][col]=pattern[i%len(pattern)]
            if top>0:o[top-1][col]=marker
            end=horiz(top,col)
            if end is not None and end!=col:vert_all(end)
    for sr in starts:
        end=horiz(sr,0,True)
        if end is not None:vert_all(end)
    return o
